function bestTreeHaul(root: TreeNode | null): number {
  if (!root) return 0;
  const order: TreeNode[] = [root];
  for (let i = 0; i < order.length; i++) {
    const n = order[i];
    if (n.left) order.push(n.left);
    if (n.right) order.push(n.right);
  }
  const take = new Map<TreeNode, number>(), skip = new Map<TreeNode, number>();
  const best = (n: TreeNode | null) => (n ? Math.max(take.get(n)!, skip.get(n)!) : 0);
  for (let i = order.length - 1; i >= 0; i--) {
    const n = order[i];
    take.set(n, n.val + (n.left ? skip.get(n.left)! : 0) + (n.right ? skip.get(n.right)! : 0));
    skip.set(n, best(n.left) + best(n.right));
  }
  return best(root);
}

